import React from 'react';
import Slider from 'react-slick';
import '../styles/ClientesCarrusel.css';

// Importa los logos de tus clientes
import logo1 from '../assets/clientes/logo1.png';
import logo2 from '../assets/clientes/logo2.png';
import logo3 from '../assets/clientes/logo3.png';
import logo4 from '../assets/clientes/logo4.png';
import logo5 from '../assets/clientes/logo5.png';
import logo6 from '../assets/clientes/logo6.png';
import logo7 from '../assets/clientes/logo7.png';
import logo8 from '../assets/clientes/logo8.png';

const logos = [logo1, logo2, logo3, logo4, logo5, logo6, logo7, logo8];

const ClientesCarrusel = () => {
  const settings = {
    dots: false,
    infinite: true,
    slidesToShow: 6,
    slidesToScroll: 1,
    autoplay: true,
    speed: 8000, // Duración de la animación (más alto = más lento)
    autoplaySpeed: 0, // Sin pausa entre transiciones
    cssEase: "linear", // Movimiento a velocidad constante
    pauseOnHover: true, // Se detiene al pasar el ratón
    arrows: false, // Oculta las flechas de navegación
    responsive: [
      {
        breakpoint: 1024,
        settings: {
          slidesToShow: 4,
        }
      },
      {
        breakpoint: 600,
        settings: {
          slidesToShow: 3,
        }
      },
      {
        breakpoint: 480,
        settings: {
          slidesToShow: 2,
        }
      }
    ]
  };

  return (
    <div className="clientes-carrusel">
      <Slider {...settings}>
        {logos.map((logo, index) => (
          <div key={index} className="cliente-logo">
            <img src={logo} alt={`Cliente ${index + 1}`} />
          </div>
        ))}
      </Slider>
    </div>
  );
};

export default ClientesCarrusel;
